<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();header('Content-Type: application/json; charset=utf-8');try{$numero=(int)(usuario()['numero_distrito']??0);if(es_control()){$id=(int)($_GET['id_distrito']??0);$s=bd()->prepare('SELECT numero_distrito FROM distritos WHERE id_distrito=?');$s->bind_param('i',$id);$s->execute();$numero=(int)($s->get_result()->fetch_row()[0]??0);}if(!$numero)throw new RuntimeException('Distrito no disponible.');$s=bd()->prepare('SELECT id,claveDT,nombreDT,dtto,claveUT,nombreUT,seccionesC,seccionesP FROM seccxut WHERE dtto=? ORDER BY claveUT,nombreUT');$s->bind_param('i',$numero);$s->execute();echo json_encode(['correcto'=>true,'unidades'=>$s->get_result()->fetch_all(MYSQLI_ASSOC)],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(400);echo json_encode(['correcto'=>false,'mensaje'=>$e->getMessage()]);}